ons":[{"en":"58"},{"en":"75"},{"en":"69"},{"en":"87"}],"category":"Cricket","domain":"sports","topic":"Cricket","subtopic":"2002 NatWest final","difficulty":"extreme","files":["sports","cricket"],"correctIndex":2,"explanation":{"en":"Yuvraj faced 63 balls and the pair added 121 before Paul Collingwood dismissed him; India won with three balls to spare."},"sourceUrl":"https://en.wikipedia.org/wiki/Yuvraj_Singh"},{"id":"cr269","prompt":{"en":"At which South African ground did Sachin Tendulkar make his 98 off 75 balls against Pakistan in the 2003 World Cup?"},"options":[{"en":"Durban"},{"en":"Johannesburg"},{"en":"Centurion"},{"en":"Cape Town"}],"category":"Cricket","domain":"sports","topic":"Cricket","subtopic":"2003 World Cup","difficulty":"simple","files":["sports","cricket"],"correctIndex":2,"explanation":{"en":"India chased 274 with more than four overs to spare after Saeed Anwar had made 101 for Pakistan; Shoaib Akhtar finally had Tendulkar caught off a bouncer."},"sourceUrl":"https://www.wisden.com/cricket-news/watch-sachin-tendulkar-shoaib-akhtar-six-ind-pak-2003-world-cup-india-pakistan"},{"id":"cr270","prompt":{"en":"By how many runs did Australia beat India in the 2003 World Cup final at the Wanderers?"},"options":[{"en":"140 runs"},{"en":"96 runs"},{"en":"77 runs"},{"en":"125 runs"}],"category":"Cricket","domain":"sports","topic":"Cricket","subtopic":"2003 World Cup final","difficulty":"expert","files":["sports","cricket"],"correctIndex":3,"explanation":{"en":"Ricky Ponting hit 140 not out with eight sixes in a total of 359 for 2; India were bowled out for 234 with Sehwag top-scoring on 82."},"sourceUrl":"https://en.wikipedia.org/wiki/2003_Cricket_World_Cup_final"},{"id":"cr271","prompt":{"en":"Which Indian bowler took 6 for 23 against England at Durban in the 2003 World Cup?"},"options":[{"en":"Zaheer Khan"},{"en":"Ashish Nehra"},{"en":"Javagal Srinath"},{"en":"Harbhajan Singh"}],"category":"Cricket","domain":"sports","topic":"Cricket","subtopic":"2003 World Cup","difficulty":"expert","files":["sports","cricket"],"correctIndex":1,"explanation":{"en":"They stayed the best World Cup figures by an Indian until Mohammed Shami bettered them in 2023; India won by 82 runs."},"sourceUrl":"https://en.wikipedia.org/wiki/Ashish_Nehra"},{"id":"cr272","prompt":{"en":"How many runs did Sachin Tendulkar score across the 2003 World Cup on his way to the player of the tournament award?"},"options":[{"en":"587"},{"en":"673"},{"en":"623"},{"en":"712"}],"category":"Cricket","domain":"sports","topic":"Cricket","subtopic":"2003 World Cup","difficulty":"extreme","files":["sports","cricket"],"correctIndex":1,"explanation":{"en":"He played 11 matches and led the run charts by a distance even though Australia won the final."},"sourceUrl":"https://en.wikipedia.org/wiki/2003_Cricket_World_Cup"},{"id":"cr273","prompt":{"en":"Who scored 233 and an unbeaten 72 as India won the Adelaide Test of December 2003 by four wickets?"},"options":[{"en":"VVS Laxman"},{"en":"Sachin Tendulkar"},{"en":"Rahul Dravid"},{"en":"Sourav Ganguly"}],"category":"Cricket","domain":"sports","topic":"Cricket","subtopic":"2003 Adelaide Test","difficulty":"simple","files":["sports","cricket"],"correctIndex":2,"explanation":{"en":"It was India's first Test win in Australia for 23 years; Dravid square-cut the winning boundary and kissed the crest on his cap."},"sourceUrl":"https://en.wikipedia.org/wiki/Rahul_Dravid"},{"id":"cr274","prompt":{"en":"Which Indian seamer took 6 for 41 to bowl Australia out for 196 in the second innings at Adelaide in 2003?"},"options":[{"en":"Ashish Nehra"},{"en":"Zaheer Khan"},{"en":"Irfan Pathan"},{"en":"Ajit Agarkar"}],"category":"Cricket","domain":"sports","topic":"Cricket","subtopic":"2003 Adelaide Test","difficulty":"expert","files":["sports","cricket"],"correctIndex":3,"explanation":{"en":"Australia had made 556 in the first innings; Dravid and Laxman replied with a 303-run stand after India were 85 for 4."},"sourceUrl":"https://en.wikipedia.org/wiki/Indian_cricket_team_in_Australia_in_2003%E2%80%9304"},{"id":"cr275","prompt":{"en":"Which Australian made 242 in the first innings at Adelaide in 2003 and still finished on the losing side?"},"options":[{"en":"Matthew Hayden"},{"en":"Ricky Ponting"},{"en":"Justin Langer"},{"en":"Steve Waugh"}],"category":"Cricket","domain":"sports","topic":"Cricket","subtopic":"2003 Adelaide Test","difficulty":"extreme","files":["sports","cricket"],"correctIndex":1,"explanation":{"en":"It was then the highest Test score in a defeat; Ponting followed it with 257 at Melbourne, where Australia won by nine wickets."},"sourceUrl":"https://en.wikipedia.org/wiki/Ricky_Ponting"},{"id":"cr276","prompt":{"en":"At which Pakistani venue did Virender Sehwag score 309, the first Test triple century by an Indian, in March 2004?"},"options":[{"en":"Lahore"},{"en":"Karachi"},{"en":"Multan"},{"en":"Rawalpindi"}],"category":"Cricket","domain":"sports","topic":"Cricket","subtopic":"2004 Pakistan tour","difficulty":"simple","files":["sports","cricket"],"correctIndex":2,"explanation":{"en":"The 309 came off 375 balls; India declared on 675 for 5 and won by an innings and 52 runs, their first Test win on Pakistani soil."},"sourceUrl":"https://en.wikipedia.org/wiki/Indian_cricket_team_in_Pakistan_in_2003%E2%80%9304"},{"id":"cr277","prompt":{"en":"On what score was Sachin Tendulkar left unbeaten when Rahul Dravid declared at Multan in 2004?"},"options":[{"en":"194"},{"en":"199"},{"en":"198"},{"en":"186"}],"category":"Cricket","domain":"sports","topic":"Cricket","subtopic":"2004 Pakistan tour","difficulty":"expert","files":["sports","cricket"],"correctIndex":0,"explanation":{"en":"Dravid, standing in as captain, wanted overs at tired Pakistani batsmen; Tendulkar was six short of a fourth Test double hundred."},"sourceUrl":"https://en.wikipedia.org/wiki/Rahul_Dravid"},{"id":"cr278","prompt":{"en":"By what margin did India win the Rawalpindi Test of 2004, in which Rahul Dravid made 270, to take the series 2-1?"},"options":[{"en":"An innings and 131 runs"},{"en":"An innings and 52 runs"},{"en":"Ten wickets"},{"en":"Eight wickets"}],"category":"Cricket","domain":"sports","topic":"Cricket","subtopic":"2004 Pakistan tour","difficulty":"extreme","files":["sports","cricket"],"correctIndex":0,"explanation":{"en":"The 270 remains Dravid's Test best; he was finally out to a reverse sweep. Pakistan had squared the series at Lahore, where Umar Gul took 5 for 31."},"sourceUrl":"https://en.wikipedia.org/wiki/Indian_cricket_team_in_Pakistan_in_2003%E2%80%9304"},{"id":"cr279","prompt":{"en":"Who bowled the final over for India in the Karachi ODI of March 2004, defending nine runs to win by five?"},"options":[{"en":"Zaheer Khan"},{"en":"Irfan Pathan"},{"en":"Ashish Nehra"},{"en":"Lakshmipathy Balaji"}],"category":"Cricket","domain":"sports","topic":"Cricket","subtopic":"2004 Karachi ODI","difficulty":"expert","files":["sports","cricket"],"correctIndex":2,"explanation":{"en":"Moin Khan needed six off the last ball and skied a full toss to cover; India had made 349 for 7 and Inzamam-ul-Haq 122 in reply."},"sourceUrl":"https://www.thecricketmonthly.com/story/1372559/greatest-odis-no-10-pakistan-vs-india-karachi-2004"},{"id":"cr280","prompt":{"en":"Which Australian was appointed India coach in May 2005 on a contract running to the 2007 World Cup?"},"options":[{"en":"John Wright"},{"en":"Greg Chappell"},{"en":"Dav Whatmore"},{"en":"Ian Chappell"}],"category":"Cricket","domain":"sports","topic":"Cricket","subtopic":"Greg Chappell era","difficulty":"simple","files":["sports","cricket"],"correctIndex":1,"explanation":{"en":"He resigned after India went out in the first round of the 2007 World Cup; Sehwag, Harbhajan and Zaheer all criticised his methods publicly."},"sourceUrl":"https://en.wikipedia.org/wiki/Greg_Chappell"},{"id":"cr281","prompt":{"en":"On the 2005 tour of which country did Sourav Ganguly score a century and then allege that Greg Chappell had asked him to step down as captain?"},"options":[{"en":"Sri Lanka"},{"en":"Bangladesh"},{"en":"West Indies"},{"en":"Zimbabwe"}],"category":"Cricket","domain":"sports","topic":"Cricket","subtopic":"Greg Chappell era","difficulty":"expert","files":["sports","cricket"],"correctIndex":3,"explanation":{"en":"Ganguly made 101 at Bulawayo in an innings win; he was dropped in October 2005 and did not return until the end of 2006."},"sourceUrl":"https://en.wikipedia.org/wiki/Greg_Chappell"},{"id":"cr282","prompt":{"en":"At which venue did MS Dhoni hit 148 off 123 balls against Pakistan in April 2005, in only his fifth ODI?"},"options":[{"en":"Visakhapatnam"},{"en":"Kochi"},{"en":"Jamshedpur"},{"en":"Ahmedabad"}],"category":"Cricket","domain":"sports","topic":"Cricket","subtopic":"MS Dhoni","difficulty":"simple","files":["sports","cricket"],"correctIndex":0,"explanation":{"en":"The innings beat the previous highest ODI score by an Indian wicketkeeper; Dhoni had been run out for a duck on debut four months earlier."},"sourceUrl":"https://en.wikipedia.org/wiki/MS_Dhoni"},{"id":"cr283","prompt":{"en":"Against which side did MS Dhoni make an unbeaten 183 at Jaipur in October 2005 after being promoted to number three?"},"options":[{"en":"Sri Lanka"},{"en":"Pakistan"},{"en":"England"},{"en":"South Africa"}],"category":"Cricket","domain":"sports","topic":"Cricket","subtopic":"MS Dhoni","difficulty":"expert","files":["sports","cricket"],"correctIndex":0,"explanation":{"en":"The 145-ball innings was then the highest ODI score in a run chase; Wisden called it uninhibited yet anything but crude."},"sourceUrl":"https://en.wikipedia.org/wiki/MS_Dhoni"},{"id":"cr284","prompt":{"en":"How was MS Dhoni dismissed for nought on his ODI debut against Bangladesh in December 2004?"},"options":[{"en":"Bowled"},{"en":"Caught behind"},{"en":"Lbw"},{"en":"Run out"}],"category":"Cricket","domain":"sports","topic":"Cricket","subtopic":"MS Dhoni","difficulty":"extreme","files":["sports","cricket"],"correctIndex":3,"explanation":{"e