n":"31"},{"en":"46"},{"en":"7"}],"category":"Cricket","domain":"sports","topic":"Cricket","subtopic":"Chepauk 1999","difficulty":"simple","files":["sports","cricket"],"correctIndex":0,"explanation":{"en":"India were 258 all out chasing 271 after Saqlain Mushtaq dismissed Tendulkar and finished with 5 for 93; Kumble squared the series with his ten at Delhi."},"sourceUrl":"https://en.wikipedia.org/wiki/Pakistani_cricket_team_in_India_in_1998%E2%80%9399"},{"id":"cr566","prompt":{"en":"Who made 141 in Pakistan's second innings of the 1999 Chennai Test to set up the 12-run win?"},"options":[{"en":"Inzamam-ul-Haq"},{"en":"Saeed Anwar"},{"en":"Yousuf Youhana"},{"en":"Shahid Afridi"}],"category":"Cricket","domain":"sports","topic":"Cricket","subtopic":"Chepauk 1999","difficulty":"extreme","files":["sports","cricket"],"correctIndex":3,"explanation":{"en":"The innings took 191 balls; Saqlain Mushtaq was player of the series after the two Tests were shared 1-1."},"sourceUrl":"https://en.wikipedia.org/wiki/Pakistani_cricket_team_in_India_in_1998%E2%80%9399"},{"id":"cr567","prompt":{"en":"Which India bowler was said to have bowled wide of off stump at Delhi in 1999 so that Anil Kumble could claim all ten Pakistan wickets?"},"options":[{"en":"Venkatesh Prasad"},{"en":"Javagal Srinath"},{"en":"Harbhajan Singh"},{"en":"Sunil Joshi"}],"category":"Cricket","domain":"sports","topic":"Cricket","subtopic":"Kumble's ten","difficulty":"expert","files":["sports","cricket"],"correctIndex":1,"explanation":{"en":"Kumble finished with 10 for 74, the second such innings after Jim Laker, and India won by 212 runs."},"sourceUrl":"https://en.wikipedia.org/wiki/Anil_Kumble"},{"id":"cr568","prompt":{"en":"In which year was the Feroz Shah Kotla ground in Delhi renamed the Arun Jaitley Stadium?"},"options":[{"en":"2015"},{"en":"2017"},{"en":"2019"},{"en":"2021"}],"category":"Cricket","domain":"sports","topic":"Cricket","subtopic":"Feroz Shah Kotla","difficulty":"simple","files":["sports","cricket"],"c