ttps://www.formula1.com/en/latest/article.brilliant-verstappen-claims-maiden-title-after-victory-in-abu-dhabi-season.22Arui4l6BKK2PUsJgKqpZ.html"},{"id":"f1046","prompt":{"en":"At which Silverstone corner did Hamilton and Verstappen collide on lap one of the 2021 British Grand Prix?"},"options":[{"en":"Stowe"},{"en":"Maggotts"},{"en":"Brooklands"},{"en":"Copse"}],"category":"Formula 1","domain":"sports","topic":"Formula 1","subtopic":"Verstappen v Hamilton","difficulty":"expert","files":["sports","formula-1"],"correctIndex":3,"explanation":{"en":"Hamilton took a 10-second penalty and still won; Verstappen went to hospital for checks."},"sourceUrl":"https://www.autosport.com/f1/news/the-details-at-the-heart-of-the-hamilton-verstappen-debate/6634406/"},{"id":"f1047","prompt":{"en":"How many lapped cars were allowed to un-lap themselves before the final-lap restart at Abu Dhabi 2021?"},"options":[{"en":"All eight"},{"en":"Five"},{"en":"Three"},{"en":"None"}],"category":"Formula 1","domain":"sports","topic":"Formula 1","subtopic":"Abu Dhabi 2021","difficulty":"extreme","files":["sports","formula-1"],"correctIndex":1,"explanation":{"en":"Race director Michael Masi let only the cars between Hamilton and Verstappen through."},"sourceUrl":"https://www.formula1.com/en/drivers/hall-of-fame/Max_Verstappen.html"},{"id":"f1048","prompt":{"en":"Which pair replaced Michael Masi as alternating race directors in February 2022?"},"options":[{"en":"Niels Wittich and Eduardo Freitas"},{"en":"Herbie Blash and Charlie Whiting"},{"en":"Tim Mayer and Rui Marques"},{"en":"Colin Haywood and Scot Elkins"}],"category":"Formula 1","domain":"sports","topic":"Formula 1","subtopic":"Abu Dhabi 2021","difficulty":"extreme","files":["sports","formula-1"],"correctIndex":0,"explanation":{"en":"Herbie Blash returned as senior advisor and team radio to the race director left the TV feed."},"sourceUrl":"https://www.formula1.com/en/latest/article.michael-masi-replaced-as-race-director-amid-fia-structural-changes.174xskJuXpEIAiXPQ98oPE.html"},{"id":"f1049","prompt":{"en":"Which aerodynamic concept, banned since the early 1980s, returned with the 2022 technical rules?"},"options":[{"en":"Active suspension"},{"en":"Fan cars"},{"en":"Ground effect"},{"en":"Six-wheelers"}],"category":"Formula 1","domain":"sports","topic":"Formula 1","subtopic":"Ground effect and the 2022 rules","difficulty":"simple","files":["sports","formula-1"],"correctIndex":2,"explanation":{"en":"Venturi tunnels under the floor now do the work wings used to, cutting the dirty-air penalty."},"sourceUrl":"https://www.autosport.com/f1/news/formula-1s-2021-regulations-what-will-the-cars-look-like-in-2022-5278037/5278037/"},{"id":"f1050","prompt":{"en":"Which hybrid component was dropped from Formula 1 power units under the 2026 engine rules?"},"options":[{"en":"MGU-H"},{"en":"MGU-K"},{"en":"Turbocharger"},{"en":"Energy store"}],"category":"Formula 1","domain":"sports","topic":"Formula 1","subtopic":"The 2026 rules","difficulty":"simple","files":["sports","formula-1"],"correctIndex":0,"explanation":{"en":"The heat-recovery motor went, and the MGU-K grew to roughly half of total power output."},"sourceUrl":"https://www.autosport.com/f1/news/fia-finalises-2026-formula-1-engines-regulations/10353609/"},{"id":"f1051","prompt":{"en":"Which overtaking aid did active aerodynamics, with its X-mode and Z-mode, replace for 2026?"},"options":[{"en":"KERS"},{"en":"Push-to-pass"},{"en":"F-duct"},{"en":"DRS"}],"category":"Formula 1","domain":"sports","topic":"Formula 1","subtopic":"The 2026 rules","difficulty":"expert","files":["sports","formula-1"],"correctIndex":3,"explanation":{"en":"Movable front and rear wing elements switch between low-drag and high-downforce settings."},"sourceUrl":"https://www.autosport.com/f1/news/how-f1s-new-active-aero-will-work-in-2026/10620099/"},{"id":"f1052","prompt":{"en":"What electrical output was set for the MGU-K under the 2026 power unit regulations?"},"options":[{"en":"120 kW"},{"en":"200 kW"},{"en":"350 kW"},{"en":"500 kW"}],"category":"Formula 1","domain":"sports","topic":"Formula 1","subtopic":"The 2026 rules","difficulty":"extreme","files":["sports","formula-1"],"correctIndex":2,"explanation":{"en":"That is about half the powertrain’s total output, with the V6 on fully sustainable fuel supplying the rest."},"sourceUrl":"https://www.autosport.com/f1/news/fia-finalises-2026-formula-1-engines-regulations/10353609/"},{"id":"f1053","prompt":{"en":"Which driver holds the record of six Monaco Grand Prix victories?"},"options":[{"en":"Graham Hill"},{"en":"Michael Schumacher"},{"en":"Ayrton Senna"},{"en":"Alain Prost"}],"category":"Formula 1","domain":"sports","topic":"Formula 1","subtopic":"Monaco","difficulty":"simple","files":["sports","formula-1"],"correctIndex":2,"explanation":{"en":"His first Monaco podium came in a Toleman in 1984, second in the rain to Prost."},"sourceUrl":"https://www.formula1.com/en/drivers/hall-of-fame/Ayrton_Senna.html"},{"id":"f1054","prompt":{"en":"Who won the 1996 Monaco Grand Prix, in which only three cars were still running at the finish?"},"options":[{"en":"David Coulthard"},{"en":"Johnny Herbert"},{"en":"Jean Alesi"},{"en":"Olivier Panis"}],"category":"Formula 1","domain":"sports","topic":"Formula 1","subtopic":"Monaco","difficulty":"expert","files":["sports","formula-1"],"correctIndex":3,"explanation":{"en":"Panis’s Ligier beat Coulthard and Herbert home; it was his only F1 win."},"sourceUrl":"https://www.formula1.com/en/results/1996/races/643/monaco/race-result"},{"id":"f1055","prompt":{"en":"Who took his first Grand Prix win at Monaco in 1982 after the leaders fell away in the final laps?"},"options":[{"en":"Didier Pironi"},{"en":"Andrea de Cesaris"},{"en":"Riccardo Patrese"},{"en":"Derek Daly"}],"category":"Formula 1","domain":"sports","topic":"Formula 1","subtopic":"Monaco","difficulty":"extreme","files":["sports","formula-1"],"correctIndex":2,"explanation":{"en":"Prost crashed, Patrese spun and recovered, Pironi stopped in the tunnel and de Cesaris ran dry."},"sourceUrl":"https://www.formula1.com/en/results/1982/races/442/monaco/race-result"},{"id":"f1056","prompt":{"en":"Which team is the only one to have competed in every Formula 1 season since 1950?"},"options":[{"en":"McLaren"},{"en":"Williams"},{"en":"Ferrari"},{"en":"Lotus"}],"category":"Formula 1","domain":"sports","topic":"Formula 1","subtopic":"Constructors' dynasties","difficulty":"simple","files":["sports","formula-1"],"correctIndex":2,"explanation":{"en":"Ferrari claimed a then-unprecedented five consecutive title doubles with Schumacher."},"sourceUrl":"https://www.formula1.com/en/teams/ferrari"},{"id":"f1057","prompt":{"en":"How many consecutive constructors' titles did Ferrari win in the Schumacher era from 1999?"},"options":[{"en":"Four"},{"en":"Six"},{"en":"Five"},{"en":"Eight"}],"category":"Formula 1","domain":"sports","topic":"Formula 1","subtopic":"Constructors' dynasties","difficulty":"expert","files":["sports","formula-1"],"correctIndex":1,"explanation":{"en":"Six straight, 1999 to 2004, a run Mercedes later passed with eight from 2014."},"sourceUrl":"https://www.formula1.com/en/drivers/hall-of-fame/Michael_Schumacher.html"},{"id":"f1058","prompt":{"en":"At which 2018 race did Mercedes clinch a fifth successive constructors' championship?"},"options":[{"en":"Brazilian Grand Prix"},{"en":"Mexican Grand Prix"},{"en":"Abu Dhabi Grand Prix"},{"en":"United States Grand Prix"}],"category":"Formula 1","domain":"sports","topic":"Formula 1","subtopic":"Constructors' dynasties","difficulty":"extreme","files":["sports","formula-1"],"correctIndex":0,"explanation":{"en":"Only the second team ever to win five in a row, one short of Ferrari’s six at the time."},"sourceUrl":"https://www.formula1.com/en/latest/article.mercedes-clinch-constructors%27-title-for-fifth-successive-year.4bsymszebKSY62cAgMcGYg.html"},{"id":"f1059","prompt":{"en":"Who won the 2008 world title by a single point with a last-lap pass for fifth at Interlagos?"},"options":[{"en":"Felipe Massa"},{"en":"Lewis Hamilton"},{"en":"Kimi Raikkonen"},{"en":"Fernando Alonso"}],"category":"Formula 1","domain":"sports","topic":"Formula 1","subtopic":"Title deciders","difficulty":"simple","files":["sports","formula-1"],"correctIndex":1,"explanation":{"en":"At 23 years and 300 days he was then the youngest champion; Massa won the race for Ferrari."},"sourceUrl":"https://www.formula1.com/en/drivers/hall-of-fame/Lewis_Hamilton.html"},{"id":"f1060","prompt":{"en":"Who is Formula 1's only posthumous world champion?"},"options":[{"en":"Jochen Rindt"},{"en":"Jim Clark"},{"en":"Ronnie Peterson"},{"en":"Gilles Villeneuve"}],"category":"Formula 1","domain":"sports","topic":"Formula 1","subtopic":"Title deciders","difficulty":"expert","files":["sports","formula-1"],"correctIndex":0,"explanation":{"en":"Rindt died in practice at Monza in September 1970 with an unassailable points lead for Lotus."},"sourceUrl":"https://www.formula1.com/en/drivers/hall-of-fame/Jochen_Rindt.html"},{"id":"bk001","prompt":{"en":"Against which team did Wilt Chamberlain score his 100 points on 2 March 1962?"},"options":[{"en":"New York Knicks"},{"en":"Boston Celtics"},{"en":"Los Angeles Lakers"},{"en":"Syracuse Nationals"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"Wilt’s 100","difficulty":"simple","files":["sports","basketball"],"correctIndex":0,"explanation":{"en":"The Warriors won 169-147 in front of just 4,124 people, though many thousands more later claimed to have been there."},"sourceUrl":"https://www.nba.com/news/history-season-review-1961-62"},{"id":"bk002","prompt":{"en":"Kobe Bryant’s 81-point game in January 2006 came against which opponent?"},"options":[{"en":"Dallas Mavericks"},{"en":"Toronto Raptors"},{"en":"Memphis Grizzlies"},{"en":"Portland Trail Blazers"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"Kobe’s 81","difficulty":"simple","files":["sports","basketball"],"correctIndex":1,"explanation":{"en":"The Lakers won 122-104; only Wilt’s 100 has ever beaten Kobe’s total in a single NBA game."},"sourceUrl":"https://www.nba.com/news/history-season-review-2005-06"},{"id":"bk003","prompt":{"en":"Which franchise ended a 52-year city title drought by overturning a 3-1 NBA Finals deficit in 2016?"},"options":[{"en":"Toronto Raptors"},{"en":"Oklahoma City Thunder"},{"en":"Cleveland Cavaliers"},{"en":"Golden State Warriors"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"The 3-1 comeback (2016)","difficulty":"simple","files":["sports","basketball"],"correctIndex":2,"explanation":{"en":"No team had ever come back from 3-1 in the Finals; LeBron averaged 36.3 points over the last three games."},"sourceUrl":"https://www.nba.com/news/history-season-review-2015-16"},{"id":"bk004","prompt":{"en":"LeBron James’s chase-down block in Game 7 of the 2016 Finals denied which Warrior?"},"options":[{"en":"Stephen Curry"},{"en":"Klay Thompson"},{"en":"Harrison Barnes"},{"en":"Andre Iguodala"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"The 3-1 comeback (2016)","difficulty":"simple","files":["sports","basketball"],"correctIndex":3,"explanation":{"en":"The block came with the score tied 89-89 and under two minutes left; Cleveland never trailed again."},"sourceUrl":"https://www.basketball-reference.com/boxscores/pbp/201606190GSW.html"},{"id":"bk005","prompt":{"en":"The 2015-16 Warriors’ 73 wins broke a regular-season record set by which team?"},"options":[{"en":"1995-96 Chicago Bulls"},{"en":"1971-72 Los Angeles Lakers"},{"en":"1985-86 Boston Celtics"},{"en":"1996-97 Chicago Bulls"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"Warriors 73-9","difficulty":"simple","files":["sports","basketball"],"correctIndex":0,"explanation":{"en":"Jordan’s Bulls went 72-10 under Phil Jackson; Golden State went 73-9 and then lost the Finals."},"sourceUrl":"https://www.nba.com/news/history-season-review-2015-16"},{"id":"bk006","prompt":{"en":"The 2004 “Malice at the Palace” brawl erupted during a Pistons home game against which visiting team?"},"options":[{"en":"Chicago Bulls"},{"en":"Indiana Pacers"},{"en":"Cleveland Cavaliers"},{"en":"Milwaukee Bucks"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"Malice at the Palace","difficulty":"simple","files":["sports","basketball"],"correctIndex":1,"explanation":{"en":"The fight on 19 November 2004 spilled into the stands at the Palace of Auburn Hills and led to lawsuits as well as suspensions."},"sourceUrl":"https://www.nba.com/news/history-season-review-2004-05"},{"id":"bk007","prompt":{"en":"Tim Donaghy, at the centre of the NBA’s 2007 betting scandal, had worked for the league in what role?"},"options":[{"en":"Team physician"},{"en":"Official scorer"},{"en":"Referee"},{"en":"Assistant coach"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"Tim Donaghy","difficulty":"simple","files":["sports","basketball"],"correctIndex":2,"explanation":{"en":"Donaghy officiated 753 regular-season games from 1994-95 to 2006-07 before his guilty plea."},"sourceUrl":"https://www.basketball-reference.com/referees/donagti99r.html"},{"id":"bk008","prompt":{"en":"Which team pushed the Lakers to a Game 7 overtime in the 2002 Western Conference finals?"},"options":[{"en":"San Antonio Spurs"},{"en":"Dallas Mavericks"},{"en":"Portland Trail Blazers"},{"en":"Sacramento Kings"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"Kings-Lakers 2002","difficulty":"simple","files":["sports","basketball"],"correctIndex":3,"explanation":{"en":"The Lakers won Game 7 112-106 in Sacramento; the series’ officiating is still argued about today."},"sourceUrl":"https://www.nba.com/news/history-season-review-2001-02"},{"id":"bk009","prompt":{"en":"After the 2004 Finals defeat, Shaquille O’Neal was traded from the Lakers to which team?"},"options":[{"en":"Miami Heat"},{"en":"Phoenix Suns"},{"en":"Cleveland Cavaliers"},{"en":"Boston Celtics"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"Shaq-Kobe split","difficulty":"simple","files":["sports","basketball"],"correctIndex":0,"explanation":{"en":"Shaq promised Miami a title on arrival and delivered it in 2006 alongside Dwyane Wade."},"sourceUrl":"https://www.nba.com/news/history-season-review-2004-05"},{"id":"bk010","prompt":{"en":"Whom did the Knicks select after winning the NBA’s first draft lottery in 1985?"},"options":[{"en":"Hakeem Olajuwon"},{"en":"Patrick Ewing"},{"en":"Karl Malone"},{"en":"Chris Mullin"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"1985 lottery","difficulty":"simple","files":["sports","basketball"],"correctIndex":1,"explanation":{"en":"Ewing made his debut on 26 October 1985 and went on to win Rookie of the Year."},"sourceUrl":"https://www.nba.com/news/history-season-review-1985-86"},{"id":"bk011","prompt":{"en":"In the 1979 NCAA final, Magic Johnson’s Michigan State beat which school led by Larry Bird?"},"options":[{"en":"Indiana"},{"en":"DePaul"},{"en":"Indiana State"},{"en":"Penn"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"Bird-Magic","difficulty":"simple","files":["sports","basketball"],"correctIndex":2,"explanation":{"en":"Michigan State won 75-64 in Salt Lake City and Magic was named Most Outstanding Player."},"sourceUrl":"https://www.sports-reference.com/cbb/postseason/men/1979-ncaa.html"},{"id":"bk012","prompt":{"en":"Magic Johnson retired days into the 1991-92 season after announcing he had contracted what?"},"options":[{"en":"Hepatitis"},{"en":"Lyme disease"},{"en":"Leukaemia"},{"en":"HIV"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"Bird-Magic","difficulty":"simple","files":["sports","basketball"],"correctIndex":3,"explanation":{"en":"Fans still voted him into the 1992 All-Star Game, where he scored 25 points and won MVP."},"sourceUrl":"https://www.nba.com/news/history-season-review-1991-92"},{"id":"bk013","prompt":{"en":"The original Dream Team won Olympic gold in 1992 in which city?"},"options":[{"en":"Barcelona"},{"en":"Atlanta"},{"en":"Seoul"},{"en":"Sydney"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"Dream Team","difficulty":"simple","files":["sports","basketball"],"correctIndex":0,"explanation":{"en":"It was the first US Olympic team to include NBA stars and beat its eight opponents by an average of 44 points."},"sourceUrl":"https://web.archive.org/web/2012id_/http://www.nba.com/history/dreamT_moments.html"},{"id":"bk014","prompt":{"en":"Who coached the 1992 Dream Team?"},"options":[{"en":"Pat Riley"},{"en":"Chuck Daly"},{"en":"Lenny Wilkens"},{"en":"Mike Krzyzewski"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"Dream Team","difficulty":"simple","files":["sports","basketball"],"correctIndex":1,"explanation":{"en":"Daly likened travelling with the team to “Elvis and the Beatles put together”."},"sourceUrl":"https://web.archive.org/web/2012id_/http://www.nba.com/history/dreamT_moments.html"},{"id":"bk015","prompt":{"en":"Which nation won men’s basketball gold at Athens 2004, with the USA settling for bronze?"},"options":[{"en":"Italy"},{"en":"Lithuania"},{"en":"Argentina"},{"en":"Spain"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"Olympic basketball","difficulty":"simple","files":["sports","basketball"],"correctIndex":2,"explanation":{"en":"Italy took silver; the shock prompted USA Basketball to rebuild its whole national-team programme."},"sourceUrl":"https://web.archive.org/web/2024id_/https://olympics.com/en/olympic-games/athens-2004/results/basketball/basketball-men"},{"id":"bk016","prompt":{"en":"Which country won the 2023 FIBA Basketball World Cup, finishing ahead of Serbia and Canada?"},"options":[{"en":"Spain"},{"en":"USA"},{"en":"Australia"},{"en":"Germany"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"FIBA World Cup","difficulty":"simple","files":["sports","basketball"],"correctIndex":3,"explanation":{"en":"Dennis Schröder was tournament MVP; the USA finished fourth in the event co-hosted by the Philippines, Japan and Indonesia."},"sourceUrl":"https://www.fiba.basketball/basketballworldcup/2023"},{"id":"bk017","prompt":{"en":"Which team won the WNBA’s first four championships, from 1997 to 2000?"},"options":[{"en":"Houston Comets"},{"en":"Los Angeles Sparks"},{"en":"New York Liberty"},{"en":"Phoenix Mercury"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"WNBA","difficulty":"simple","files":["sports","basketball"],"correctIndex":0,"explanation":{"en":"Behind Cynthia Cooper, Sheryl Swoopes and Tina Thompson, Houston won every title of the league’s first four seasons before the franchise folded in 2008."},"sourceUrl":"https://www.wnba.com/all-time-wnba-champions/"},{"id":"bk018","prompt":{"en":"Caitlin Clark won the 2024 WNBA Rookie of the Year award with which team?"},"options":[{"en":"Chicago Sky"},{"en":"Indiana Fever"},{"en":"Las Vegas Aces"},{"en":"Dallas Wings"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"WNBA","difficulty":"simple","files":["sports","basketball"],"correctIndex":1,"explanation":{"en":"A’ja Wilson of Las Vegas was the league MVP that same season."},"sourceUrl":"https://www.wnba.com/awards2024"},{"id":"bk019","prompt":{"en":"Whom did the Lakers beat in the 2020 Finals played inside the Disney World bubble?"},"options":[{"en":"Boston Celtics"},{"en":"Denver Nuggets"},{"en":"Miami Heat"},{"en":"Milwaukee Bucks"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"The 2020 bubble","difficulty":"simple","files":["sports","basketball"],"correctIndex":2,"explanation":{"en":"LeBron closed the series with 28 points, 14 rebounds and 10 assists in Game 6 and nobody tested positive in three months on campus."},"sourceUrl":"https://www.nba.com/news/history-season-review-2019-20"},{"id":"bk020","prompt":{"en":"Jordan’s final shot as a Bull, the 1998 Finals winner with 5.2 seconds left, beat which team?"},"options":[{"en":"Seattle SuperSonics"},{"en":"Phoenix Suns"},{"en":"Portland Trail Blazers"},{"en":"Utah Jazz"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"Jordan’s Bulls","difficulty":"simple","files":["sports","basketball"],"correctIndex":3,"explanation":{"en":"He scored 45 in that Game 6, making the steal and then the jumper that won it 87-86."},"sourceUrl":"https://www.nba.com/news/history-season-review-1997-98"},{"id":"bk021","prompt":{"en":"Wilt’s 100-point game was played not in Philadelphia but in which Pennsylvania town?"},"options":[{"en":"Allentown"},{"en":"Scranton"},{"en":"Hershey"},{"en":"Pittsburgh"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"Wilt’s 100","difficulty":"expert","files":["sports","basketball"],"correctIndex":2,"explanation":{"en":"The venue was the Hershey Sports Arena; Richie Guerin’s 39 for New York went almost unnoticed."},"sourceUrl":"https://www.basketball-reference.com/boxscores/196203020NYK.html"},{"id":"bk022","prompt":{"en":"How many of Kobe Bryant’s 81 points came after half-time?"},"options":[{"en":"41"},{"en":"48"},{"en":"55"},{"en":"62"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"Kobe’s 81","difficulty":"expert","files":["sports","basketball"],"correctIndex":2,"explanation":{"en":"He had 26 at the break, then went 18-of-28 from the field in the second half as the Lakers came from behind."},"sourceUrl":"https://www.basketball-reference.com/boxscores/200601220LAL.html"},{"id":"bk023","prompt":{"en":"Who hit the go-ahead three-pointer with 53 seconds left in Game 7 of the 2016 Finals?"},"options":[{"en":"Kyrie Irving"},{"en":"LeBron James"},{"en":"J.R. Smith"},{"en":"Kevin Love"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"The 3-1 comeback (2016)","difficulty":"expert","files":["sports","basketball"],"correctIndex":0,"explanation":{"en":"The 25-footer broke an 89-89 tie; Irving finished with 26 points."},"sourceUrl":"https://www.basketball-reference.com/boxscores/pbp/201606190GSW.html"},{"id":"bk024","prompt":{"en":"Which Warrior sat out Game 5 of the 2016 Finals through suspension, with Golden State leading 3-1?"},"options":[{"en":"Andrew Bogut"},{"en":"Draymond Green"},{"en":"Festus Ezeli"},{"en":"Klay Thompson"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"The 3-1 comeback (2016)","difficulty":"expert","files":["sports","basketball"],"correctIndex":1,"explanation":{"en":"Cleveland won that game 112-97 in Oakland and the Warriors never won again in the series."},"sourceUrl":"https://www.basketball-reference.com/boxscores/201606130GSW.html"},{"id":"bk025","prompt":{"en":"How many three-pointers did Stephen Curry make in the 2015-16 regular season, the first time anyone passed 400?"},"options":[{"en":"386"},{"en":"414"},{"en":"402"},{"en":"373"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"Warriors 73-9","difficulty":"expert","files":["sports","basketball"],"correctIndex":2,"explanation":{"en":"He broke his own record on the way to becoming the NBA’s first unanimous MVP."},"sourceUrl":"https://www.nba.com/news/history-season-review-2015-16"},{"id":"bk026","prompt":{"en":"Nine players were suspended after the Malice at the Palace for a combined total of how many games?"},"options":[{"en":"86"},{"en":"120"},{"en":"172"},{"en":"146"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"Malice at the Palace","difficulty":"expert","files":["sports","basketball"],"correctIndex":3,"explanation":{"en":"Ron Artest, the first player into the stands, was banned for the rest of the season."},"sourceUrl":"https://www.nba.com/news/history-season-review-2004-05"},{"id":"bk027","prompt":{"en":"In which year did Tim Donaghy plead guilty in federal court in Brooklyn?"},"options":[{"en":"2007"},{"en":"2005"},{"en":"2008"},{"en":"2010"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"Tim Donaghy","difficulty":"expert","files":["sports","basketball"],"correctIndex":0,"explanation":{"en":"He admitted two felonies on 15 August 2007, including conspiracy to commit wire fraud."},"sourceUrl":"https://web.archive.org/web/2009id_/http://www.nba.com/media/PedowitzReport.pdf"},{"id":"bk028","prompt":{"en":"After escaping Sacramento in 2002, whom did the Lakers sweep in the Finals to complete their three-peat?"},"options":[{"en":"Boston Celtics"},{"en":"New Jersey Nets"},{"en":"Indiana Pacers"},{"en":"Philadelphia 76ers"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"Kings-Lakers 2002","difficulty":"expert","files":["sports","basketball"],"correctIndex":1,"explanation":{"en":"Shaq averaged 36.3 points in the sweep and joined Jordan as the only men with three straight Finals MVPs."},"sourceUrl":"https://www.nba.com/news/history-season-review-2001-02"},{"id":"bk029","prompt":{"en":"Who was Finals MVP when Detroit beat the Lakers’ “Big Four” in five games in 2004?"},"options":[{"en":"Ben Wallace"},{"en":"Richard Hamilton"},{"en":"Chauncey Billups"},{"en":"Rasheed Wallace"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"Shaq-Kobe split","difficulty":"expert","files":["sports","basketball"],"correctIndex":2,"explanation":{"en":"“Mr. Big Shot” outplayed a Lakers side that had added Karl Malone and Gary Payton to Shaq and Kobe."},"sourceUrl":"https://www.nba.com/news/history-season-review-2003-04"},{"id":"bk030","prompt":{"en":"Patrick Ewing arrived at the Knicks from which college?"},"options":[{"en":"Syracuse"},{"en":"St. John’s"},{"en":"North Carolina"},{"en":"Georgetown"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"1985 lottery","difficulty":"expert","files":["sports","basketball"],"correctIndex":3,"explanation":{"en":"His rookie class also included Karl Malone, Joe Dumars and Chris Mullin."},"sourceUrl":"https://www.nba.com/news/history-season-review-1985-86"},{"id":"bk031","prompt":{"en":"Magic Johnson’s Game 4 winner in the 1987 Finals borrowed which teammate’s signature shot?"},"options":[{"en":"Kareem Abdul-Jabbar’s sky-hook"},{"en":"James Worthy’s finger roll"},{"en":"Byron Scott’s pull-up jumper"},{"en":"Michael Cooper’s corner three"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"Bird-Magic","difficulty":"expert","files":["sports","basketball"],"correctIndex":0,"explanation":{"en":"“You expect to lose on a sky-hook,” Bird said afterwards. “You don’t expect it to be from Magic.”"},"sourceUrl":"https://www.nba.com/news/history-season-review-1986-87"},{"id":"bk032","prompt":{"en":"Who was Finals MVP in 1985, when the Lakers beat the Celtics in a Finals for the first time ever?"},"options":[{"en":"Magic Johnson"},{"en":"Kareem Abdul-Jabbar"},{"en":"James Worthy"},{"en":"Byron Scott"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"Bird-Magic","difficulty":"expert","files":["sports","basketball"],"correctIndex":1,"explanation":{"en":"Los Angeles clinched in Game 6 at Boston Garden, silencing a building where the Celtics had lost only one Finals before."},"sourceUrl":"https://www.nba.com/news/history-season-review-1984-85"},{"id":"bk033","prompt":{"en":"The Dream Team won the 1992 gold-medal game 117-85 against which country?"},"options":[{"en":"Lithuania"},{"en":"Unified Team"},{"en":"Croatia"},{"en":"Brazil"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"Dream Team","difficulty":"expert","files":["sports","basketball"],"correctIndex":2,"explanation":{"en":"Croatia took silver and Lithuania bronze; the closest anyone got to the Americans all tournament was 32 points."},"sourceUrl":"https://web.archive.org/web/2012id_/http://www.usab.com/mens/national/moly_1992.html"},{"id":"bk034","prompt":{"en":"The USA’s first ever Olympic basketball defeat came in the 1972 Munich final by what score?"},"options":[{"en":"50-49"},{"en":"51-50"},{"en":"52-51"},{"en":"49-48"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"Olympic basketball","difficulty":"expert","files":["sports","basketball"],"correctIndex":1,"explanation":{"en":"Doug Collins’s free throws had put the USA ahead before the final three seconds were replayed and Aleksander Belov scored for the Soviets."},"sourceUrl":"https://web.archive.org/web/2013id_/http://www.usab.com/mens/national/moly_1972.html"},{"id":"bk035","prompt":{"en":"Which team did the USA’s “Redeem Team” beat 118-107 in the Beijing 2008 final?"},"options":[{"en":"Argentina"},{"en":"Greece"},{"en":"Lithuania"},{"en":"Spain"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"Olympic basketball","difficulty":"expert","files":["sports","basketball"],"correctIndex":3,"explanation":{"en":"Argentina, the 2004 champions, took bronze; the USA went 8-0 after the bronze-medal embarrassment of Athens."},"sourceUrl":"https://web.archive.org/web/2012id_/http://www.usab.com/mens/national/moly_2008.html"},{"id":"bk036","prompt":{"en":"Who was tournament MVP when Spain won the 2019 FIBA World Cup in China?"},"options":[{"en":"Ricky Rubio"},{"en":"Pau Gasol"},{"en":"Marc Gasol"},{"en":"Sergio Llull"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"FIBA World Cup","difficulty":"expert","files":["sports","basketball"],"correctIndex":0,"explanation":{"en":"Spain beat Argentina in the final; France took bronze and the USA finished seventh."},"sourceUrl":"https://www.fiba.basketball/basketballworldcup/2019"},{"id":"bk037","prompt":{"en":"Who won the WNBA’s first Most Valuable Player award, in 1997?"},"options":[{"en":"Sheryl Swoopes"},{"en":"Lisa Leslie"},{"en":"Cynthia Cooper"},{"en":"Tina Thompson"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"WNBA","difficulty":"expert","files":["sports","basketball"],"correctIndex":2,"explanation":{"en":"Cooper’s Houston coach Van Chancellor was Coach of the Year and Teresa Weatherspoon the first Defensive Player of the Year."},"sourceUrl":"https://www.wnba.com/awards1997"},{"id":"bk038","prompt":{"en":"In 2008, which player won WNBA MVP and Rookie of the Year in the same season?"},"options":[{"en":"Maya Moore"},{"en":"Candace Parker"},{"en":"Diana Taurasi"},{"en":"Sylvia Fowles"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"WNBA","difficulty":"expert","files":["sports","basketball"],"correctIndex":1,"explanation":{"en":"Parker did it for the Los Angeles Sparks, who had drafted her first overall."},"sourceUrl":"https://www.wnba.com/awards2008"},{"id":"bk039","prompt":{"en":"On 26 August 2020 the Bucks refused to take the court for Game 5 against which opponent, halting the playoffs?"},"options":[{"en":"Miami Heat"},{"en":"Indiana Pacers"},{"en":"Orlando Magic"},{"en":"Toronto Raptors"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"The 2020 bubble","difficulty":"expert","files":["sports","basketball"],"correctIndex":2,"explanation":{"en":"The walkout protested the police shooting of Jacob Blake in Kenosha, 40 miles from Milwaukee, and spread to other leagues that day."},"sourceUrl":"https://www.nba.com/news/history-season-review-2019-20"},{"id":"bk040","prompt":{"en":"How many points did a flu-stricken Michael Jordan score in Game 5 of the 1997 Finals in Utah?"},"options":[{"en":"45"},{"en":"33"},{"en":"41"},{"en":"38"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"Jordan’s Bulls","difficulty":"expert","files":["sports","basketball"],"correctIndex":3,"explanation":{"en":"The Bulls won 90-88 with Jordan playing 44 minutes and going 13-of-27 from the field."},"sourceUrl":"https://www.basketball-reference.com/boxscores/199706110UTA.html"},{"id":"bk041","prompt":{"en":"A notoriously poor foul shooter, how many of his 32 free throws did Wilt make in the 100-point game?"},"options":[{"en":"20"},{"en":"28"},{"en":"24"},{"en":"32"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"Wilt’s 100","difficulty":"extreme","files":["sports","basketball"],"correctIndex":1,"explanation":{"en":"He also went 36-of-63 from the field; the 36 field goals and 63 attempts were both records."},"sourceUrl":"https://www.basketball-reference.com/boxscores/196203020NYK.html"},{"id":"bk042","prompt":{"en":"How many three-pointers did Kobe Bryant make on his way to 81 points?"},"options":[{"en":"5"},{"en":"9"},{"en":"7"},{"en":"11"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"Kobe’s 81","difficulty":"extreme","files":["sports","basketball"],"correctIndex":2,"explanation":{"en":"He was 7-of-13 from deep, 28-of-46 overall and 18-of-20 at the line in under 42 minutes."},"sourceUrl":"https://www.basketball-reference.com/boxscores/200601220LAL.html"},{"id":"bk043","prompt":{"en":"What was the final score of Game 7 of the 2016 Finals in Oakland?"},"options":[{"en":"95-91"},{"en":"97-93"},{"en":"89-87"},{"en":"93-89"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"The 3-1 comeback (2016)","difficulty":"extreme","files":["sports","basketball"],"correctIndex":3,"explanation":{"en":"LeBron had a 27-11-11 triple-double while Draymond Green’s 32 points led the losing side."},"sourceUrl":"https://www.basketball-reference.com/boxscores/201606190GSW.html"},{"id":"bk044","prompt":{"en":"While Steve Kerr recovered from back surgery, who coached the Warriors to a 39-4 start in 2015-16?"},"options":[{"en":"Luke Walton"},{"en":"Ron Adams"},{"en":"Alvin Gentry"},{"en":"Mike Brown"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"Warriors 73-9","difficulty":"extreme","files":["sports","basketball"],"correctIndex":0,"explanation":{"en":"Walton was interim coach from 27 October 2015 to 20 January 2016, but the wins were credited to Kerr."},"sourceUrl":"https://www.basketball-reference.com/teams/GSW/2016.html"},{"id":"bk045","prompt":{"en":"Which referee, later jailed for betting on games, was one of the three officials at the Malice at the Palace?"},"options":[{"en":"Dick Bavetta"},{"en":"Tim Donaghy"},{"en":"Joey Crawford"},{"en":"Steve Javie"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"Malice at the Palace","difficulty":"extreme","files":["sports","basketball"],"correctIndex":1,"explanation":{"en":"Donaghy worked the game with Ron Garretson and Tommy Nunez Jr.; the final score stood at 97-82 to Indiana."},"sourceUrl":"https://www.basketball-reference.com/boxscores/200411190DET.html"},{"id":"bk046","prompt":{"en":"Which lawyer’s October 2008 report to the NBA Board of Governors reviewed the Donaghy scandal and referee gambling?"},"options":[{"en":"George Mitchell"},{"en":"Kenneth Starr"},{"en":"Lawrence Pedowitz"},{"en":"Louis Freeh"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"Tim Donaghy","difficulty":"extreme","files":["sports","basketball"],"correctIndex":2,"explanation":{"en":"Pedowitz, of Wachtell, Lipton, Rosen & Katz, found Donaghy had bet on games he officiated with co-conspirators James Battista and Thomas Martino."},"sourceUrl":"https://web.archive.org/web/2009id_/http://www.nba.com/media/PedowitzReport.pdf"},{"id":"bk047","prompt":{"en":"In the infamous fourth quarter of Game 6 of the 2002 Western finals, how many free throws did the Lakers attempt?"},"options":[{"en":"18"},{"en":"22"},{"en":"34"},{"en":"27"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"Kings-Lakers 2002","difficulty":"extreme","files":["sports","basketball"],"correctIndex":3,"explanation":{"en":"They made 21 of 27 in the quarter while Sacramento shot nine; the Lakers won 106-102 to force Game 7."},"sourceUrl":"https://www.basketball-reference.com/boxscores/200205310LAL.html"},{"id":"bk048","prompt":{"en":"Which player came to the Lakers from Miami in the July 2004 trade that sent Shaq east?"},"options":[{"en":"Lamar Odom"},{"en":"Kwame Brown"},{"en":"Smush Parker"},{"en":"Vlade Divac"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"Shaq-Kobe split","difficulty":"extreme","files":["sports","basketball"],"correctIndex":0,"explanation":{"en":"Odom, Caron Butler, Brian Grant and two picks (one became Jordan Farmar) were the return; Divac was signed as a free agent a week later."},"sourceUrl":"https://www.basketball-reference.com/teams/LAL/2005_transactions.html"},{"id":"bk049","prompt":{"en":"Who went second overall, to Indiana, straight after Ewing in the 1985 draft?"},"options":[{"en":"Benoit Benjamin"},{"en":"Wayman Tisdale"},{"en":"Xavier McDaniel"},{"en":"Chris Mullin"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"1985 lottery","difficulty":"extreme","files":["sports","basketball"],"correctIndex":1,"explanation":{"en":"The Oklahoma forward was followed by Benoit Benjamin to the Clippers and Xavier McDaniel to Seattle."},"sourceUrl":"https://www.basketball-reference.com/draft/NBA_1985.html"},{"id":"bk050","prompt":{"en":"Whose steal of a James Worthy pass in Game 2 of the 1984 Finals turned that series for Boston?"},"options":[{"en":"Dennis Johnson"},{"en":"Danny Ainge"},{"en":"Gerald Henderson"},{"en":"M.L. Carr"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"Bird-Magic","difficulty":"extreme","files":["sports","basketball"],"correctIndex":2,"explanation":{"en":"The Lakers led by two with 18 seconds left; Henderson’s layup forced overtime and Boston won the series in seven."},"sourceUrl":"https://www.nba.com/news/history-season-review-1983-84"},{"id":"bk051","prompt":{"en":"Who was the only college player on the 1992 Dream Team?"},"options":[{"en":"Shaquille O’Neal"},{"en":"Alonzo Mourning"},{"en":"Grant Hill"},{"en":"Christian Laettner"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"Dream Team","difficulty":"extreme","files":["sports","basketball"],"correctIndex":3,"explanation":{"en":"The Duke forward, the best college player of 1991-92, completed a roster of eleven NBA stars."},"sourceUrl":"https://web.archive.org/web/2012id_/http://www.usab.com/mens/national/moly_1992.html"},{"id":"bk052","prompt":{"en":"Who coached the 1972 USA team that voted unanimously to refuse its silver medals?"},"options":[{"en":"Henry Iba"},{"en":"Dean Smith"},{"en":"Bob Knight"},{"en":"John Thompson"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"Olympic basketball","difficulty":"extreme","files":["sports","basketball"],"correctIndex":0,"explanation":{"en":"The defeat ended a 63-game Olympic winning streak and a run of seven straight golds; the US protest was rejected by FIBA."},"sourceUrl":"https://web.archive.org/web/2013id_/http://www.usab.com/mens/national/moly_1972.html"},{"id":"bk053","prompt":{"en":"Which country beat John Thompson’s USA 82-76 in the 1988 Seoul semifinal, the last Olympics before NBA players?"},"options":[{"en":"Yugoslavia"},{"en":"Soviet Union"},{"en":"Australia"},{"en":"Brazil"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"Olympic basketball","difficulty":"extreme","files":["sports","basketball"],"correctIndex":1,"explanation":{"en":"The Soviets took gold, Yugoslavia silver and the USA bronze; four years later the Dream Team arrived."},"sourceUrl":"https://web.archive.org/web/2012id_/http://www.usab.com/mens/national/moly_1988.html"},{"id":"bk054","prompt":{"en":"In what position did the USA finish at the 2019 FIBA World Cup?"},"options":[{"en":"4th"},{"en":"5th"},{"en":"9th"},{"en":"7th"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"FIBA World Cup","difficulty":"extreme","files":["sports","basketball"],"correctIndex":3,"explanation":{"en":"Australia, Serbia and the Czech Republic all placed above a US squad missing most of its stars."},"sourceUrl":"https://www.fiba.basketball/basketballworldcup/2019"},{"id":"bk055","prompt":{"en":"Which country hosted and won the first FIBA World Championship in 1950?"},"options":[{"en":"Brazil"},{"en":"Argentina"},{"en":"USA"},{"en":"Uruguay"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"FIBA World Cup","difficulty":"extreme","files":["sports","basketball"],"correctIndex":1,"explanation":{"en":"The USA finished second and Chile third; Argentina would not win the event again."},"sourceUrl":"https://www.fiba.basketball/en/history/201-fiba-basketball-world-cup"},{"id":"bk056","prompt":{"en":"Who was MVP of the first WNBA All-Star Game, played in New York in 1999?"},"options":[{"en":"Tina Thompson"},{"en":"Cynthia Cooper"},{"en":"Teresa Weatherspoon"},{"en":"Lisa Leslie"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"WNBA","difficulty":"extreme","files":["sports","basketball"],"correctIndex":3,"explanation":{"en":"The West won 79-61; Leslie won the honour again in 2001 and 2002."},"sourceUrl":"https://www.wnba.com/all-time-wnba-all-star-game-results/"},{"id":"bk057","prompt":{"en":"Which franchise won its only WNBA title in 2005, the first year of the best-of-five Finals?"},"options":[{"en":"Sacramento Monarchs"},{"en":"Detroit Shock"},{"en":"Connecticut Sun"},{"en":"Charlotte Sting"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"WNBA","difficulty":"extreme","files":["sports","basketball"],"correctIndex":0,"explanation":{"en":"Yolanda Griffith was Finals MVP as Sacramento beat Connecticut 3-1."},"sourceUrl":"https://www.wnba.com/all-time-wnba-champions/"},{"id":"bk058","prompt":{"en":"Which Pacer scored 53 points against Philadelphia in Indiana’s first game inside the 2020 bubble?"},"options":[{"en":"Victor Oladipo"},{"en":"T.J. Warren"},{"en":"Domantas Sabonis"},{"en":"Malcolm Brogdon"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"The 2020 bubble","difficulty":"extreme","files":["sports","basketball"],"correctIndex":1,"explanation":{"en":"Warren shot 20-of-29 and 9-of-12 from three in a 127-121 win on 1 August 2020."},"sourceUrl":"https://www.basketball-reference.com/boxscores/202008010IND.html"},{"id":"bk059","prompt":{"en":"Which jersey number did Michael Jordan wear on his March 1995 comeback before reverting to 23?"},"options":[{"en":"12"},{"en":"9"},{"en":"45"},{"en":"32"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"Jordan’s Bulls","difficulty":"extreme","files":["sports","basketball"],"correctIndex":2,"explanation":{"en":"He had sat out 17 months playing baseball; the switch back to 23 came during that spring’s playoffs."},"sourceUrl":"https://www.nba.com/news/history-season-review-1994-95"},{"id":"bk060","prompt":{"en":"“The Shot” over Cleveland in 1989 came in Game 5 of the first round at which arena?"},"options":[{"en":"Chicago Stadium"},{"en":"Richfield Coliseum"},{"en":"Gund Arena"},{"en":"Cleveland Arena"}],"category":"Basketball","domain":"sports","topic":"Basketball","subtopic":"Jordan’s Bulls","difficulty":"extreme","files":["sports","basketball"],"correctIndex":1,"explanation":{"en":"Jordan scored 44 in the 101-100 win on 7 May 1989 at the Coliseum in Richfield, Ohio."},"sourceUrl":"https://www.basketball-reference.com/boxscores/198905070CLE.html"}]$jhk_bank$::jsonb) item on conflict(id) do update set payload=excluded.payload;
